class Codec {
  public String encode(List<String> strs) {
    StringBuilder encoded = new StringBuilder();
    for (String s : strs) {
      encoded.append(s.length()).append('#').append(s);
    }
    return encoded.toString();
  }

  public List<String> decode(String s) {
    List<String> answer = new ArrayList<>();
    int index = 0;
    while (index < s.length()) {
      int delimiter = index;
      while (s.charAt(delimiter) != '#') delimiter++;
      int length = Integer.parseInt(s.substring(index, delimiter));
      int start = delimiter + 1;
      answer.add(s.substring(start, start + length));
      index = start + length;
    }
    return answer;
  }
}

class Solution {
  public String longestPalindrome(String s) {
    int bestStart = 0;
    int bestLength = 1;
    for (int center = 0; center < s.length(); center++) {
      int odd = expand(s, center, center);
      int even = expand(s, center, center + 1);
      int length = Math.max(odd, even);
      if (length > bestLength) {
        bestLength = length;
        bestStart = center - (length - 1) / 2;
      }
    }
    return s.substring(bestStart, bestStart + bestLength);
  }

  private int expand(String s, int left, int right) {
    while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
      left--;
      right++;
    }
    return right - left - 1;
  }
}

class Solution {
  public int countSubstrings(String s) {
    int count = 0;
    for (int center = 0; center < s.length(); center++) {
      count += expand(s, center, center);
      count += expand(s, center, center + 1);
    }
    return count;
  }

  private int expand(String s, int left, int right) {
    int count = 0;
    while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
      count++;
      left--;
      right++;
    }
    return count;
  }
}

class Solution {
  public boolean checkValidString(String s) {
    int low = 0;
    int high = 0;
    for (int i = 0; i < s.length(); i++) {
      char ch = s.charAt(i);
      if (ch == '(') {
        low++;
        high++;
      } else if (ch == ')') {
        low = Math.max(0, low - 1);
        high--;
      } else {
        low = Math.max(0, low - 1);
        high++;
      }
      if (high < 0) return false;
    }
    return low == 0;
  }
}

class Solution {
  public int strStr(String haystack, String needle) {
    int[] lps = buildLps(needle);
    int j = 0;
    for (int i = 0; i < haystack.length(); i++) {
      while (j > 0 && haystack.charAt(i) != needle.charAt(j)) j = lps[j - 1];
      if (haystack.charAt(i) == needle.charAt(j)) j++;
      if (j == needle.length()) return i - needle.length() + 1;
    }
    return -1;
  }

  private int[] buildLps(String pattern) {
    int[] lps = new int[pattern.length()];
    for (int i = 1, len = 0; i < pattern.length(); i++) {
      while (len > 0 && pattern.charAt(i) != pattern.charAt(len)) len = lps[len - 1];
      if (pattern.charAt(i) == pattern.charAt(len)) lps[i] = ++len;
    }
    return lps;
  }
}

class Solution {
  public boolean repeatedSubstringPattern(String s) {
    int n = s.length();
    int[] lps = new int[n];
    for (int i = 1; i < n; i++) {
      int length = lps[i - 1];
      while (length > 0 && s.charAt(i) != s.charAt(length)) {
        length = lps[length - 1];
      }
      if (s.charAt(i) == s.charAt(length)) length++;
      lps[i] = length;
    }
    int border = lps[n - 1];
    int period = n - border;
    return border > 0 && n % period == 0;
  }
}

class Solution {
  public int compress(char[] chars) {
    int write = 0;
    int read = 0;
    while (read < chars.length) {
      char current = chars[read];
      int start = read;
      while (read < chars.length && chars[read] == current) read++;
      chars[write++] = current;
      int count = read - start;
      if (count > 1) {
        String digits = String.valueOf(count);
        for (int i = 0; i < digits.length(); i++) chars[write++] = digits.charAt(i);
      }
    }
    return write;
  }
}

class Solution {
  public String reverseWords(String s) {
    StringBuilder answer = new StringBuilder();
    int index = s.length() - 1;
    while (index >= 0) {
      while (index >= 0 && s.charAt(index) == ' ') index--;
      if (index < 0) break;
      int end = index;
      while (index >= 0 && s.charAt(index) != ' ') index--;
      if (answer.length() > 0) answer.append(' ');
      answer.append(s, index + 1, end + 1);
    }
    return answer.toString();
  }
}

class Solution {
  public String convert(String s, int numRows) {
    if (numRows == 1 || numRows >= s.length()) return s;
    StringBuilder[] rows = new StringBuilder[numRows];
    for (int i = 0; i < numRows; i++) rows[i] = new StringBuilder();

    int row = 0;
    int direction = 1;
    for (int i = 0; i < s.length(); i++) {
      rows[row].append(s.charAt(i));
      if (row == 0) direction = 1;
      else if (row == numRows - 1) direction = -1;
      row += direction;
    }

    StringBuilder answer = new StringBuilder();
    for (StringBuilder current : rows) answer.append(current);
    return answer.toString();
  }
}

class Solution {
  public String addStrings(String num1, String num2) {
    StringBuilder reversed = new StringBuilder();
    int i = num1.length() - 1;
    int j = num2.length() - 1;
    int carry = 0;
    while (i >= 0 || j >= 0 || carry != 0) {
      int sum = carry;
      if (i >= 0) sum += num1.charAt(i--) - '0';
      if (j >= 0) sum += num2.charAt(j--) - '0';
      reversed.append(sum % 10);
      carry = sum / 10;
    }
    return reversed.reverse().toString();
  }
}

